  "offline.recovery.permitExpired": { "zh-TW": "離線授權已到期", en: "Offline permit expired", ja: "オフライン許可期限切れ", ko: "오프라인 권한 만료", vi: "Quyền ngoại tuyến đã hết hạn", th: "สิทธิ์ออฟไลน์หมดอายุ" },
  "offline.recovery.menuExpired": { "zh-TW": "離線菜單已到期", en: "Offline menu expired", ja: "オフラインメニュー期限切れ", ko: "오프라인 메뉴 만료", vi: "Menu ngoại tuyến đã hết hạn", th: "เมนูออฟไลน์หมดอายุ" },
  "offline.recovery.expiredDescription": { "zh-TW": "既有未同步資料仍保留，但不可建立新訂單；請恢復連線後重新初始化。", en: "Existing unsynced data is retained, but new orders are blocked. Reconnect and initialize again.", ja: "既存の未同期データは保持されますが、新規注文は作成できません。再接続して再初期化してください。", ko: "기존 미동기화 데이터는 보관되지만 새 주문은 만들 수 없습니다. 다시 연결한 후 초기화하세요.", vi: "Dữ liệu chưa đồng bộ vẫn được giữ nhưng không thể tạo đơn mới. Hãy kết nối lại và khởi tạo lại.", th: "ข้อมูลที่ยังไม่ซิงค์จะถูกเก็บไว้ แต่สร้างออเดอร์ใหม่ไม่ได้ โปรดเชื่อมต่อและเตรียมข้อมูลใหม่" },
  "offline.recovery.ordersTitle": { "zh-TW": "本機待同步訂單", en: "Local orders pending sync", ja: "端末の同期待ち注文", ko: "동기화 대기 로컬 주문", vi: "Đơn cục bộ chờ đồng bộ", th: "ออเดอร์ในเครื่องที่รอซิงค์" },
  "offline.recovery.ordersDescription": { "zh-TW": "重新載入或關閉後再開啟，資料仍保留於此裝置。", en: "Data remains on this device after reload or reopening.", ja: "再読み込みや再起動後もデータは端末に保持されます。", ko: "새로고침하거나 다시 열어도 데이터는 이 기기에 남아 있습니다.", vi: "Dữ liệu vẫn còn trên thiết bị sau khi tải lại hoặc mở lại.", th: "ข้อมูลยังอยู่ในอุปกรณ์แม้รีโหลดหรือปิดแล้วเปิดใหม่" },
